void HierarchicalBitmapRequester::PrepareForEncoding(void)
{
  // Call the common build function to prepare necessary components
  BuildCommon();

  // Allocate and initialize memory for encoding MCU lines if not already allocated
  if (m_encodingMCU == NULL) {
    m_encodingMCU = (struct Line **)m_environment->AllocateMemory(sizeof(struct Line *) * m_componentCount * 8);
    memset(m_encodingMCU, 0, sizeof(struct Line *) * m_componentCount * 8);
  }

  // Allocate and initialize memory for downsamplers if not already allocated
  if (m_downsampler == NULL) {
    m_downsampler = (class DownsamplerBase **)m_environment->AllocateMemory(sizeof(class DownsamplerBase *) * m_componentCount);
    memset(m_downsampler, 0, sizeof(class DownsamplerBase *) * m_componentCount);

    // Iterate over each component to determine if downsampling is needed
    for (int componentIndex = 0; componentIndex < m_componentCount; ++componentIndex) {
      class Component *component = m_frame->ComponentOf(componentIndex);
      int subX = component->SubXOf();
      int subY = component->SubYOf();

      // Create a downsampler for components that require subsampling
      if (subX > 1 || subY > 1) {
        m_downsampler[componentIndex] = DownsamplerBase::CreateDownsampler(
          m_environment, subX, subY, m_pixelWidth, m_pixelHeight,
          m_frame->TablesOf().IsDownsamplingInterpolated());
        m_subsampling = true;
      }
    }
  }

  // Prepare the largest scale component for encoding if it exists
  if (m_largestScale)
    m_largestScale->PrepareForEncoding();
}
